import fs from 'bare-fs';
import crypto from 'bare-crypto';
import { nowMs } from '../../profiling/index.js';
import {} from 'bare-buffer';
export async function calculateFileChecksum(filePath) {
    return new Promise((resolve, reject) => {
        try {
            const hash = crypto.createHash('sha-256');
            const stream = fs.createReadStream(filePath);
            stream.on('data', (chunk) => {
                hash.update(chunk);
            });
            stream.on('end', () => {
                resolve(hash.digest('hex'));
            });
            stream.on('error', (error) => {
                reject(new Error(`Checksum calculation error: ${error.message}`));
            });
        }
        catch (error) {
            reject(error instanceof Error ? error : new Error(`Checksum calculation error: ${String(error)}`));
        }
    });
}
export async function measureChecksum(filePath, hooks) {
    const start = nowMs();
    const checksum = await calculateFileChecksum(filePath);
    hooks?.addChecksumValidationTimeMs?.(nowMs() - start);
    return checksum;
}
